    nom:'Charlemagne',img:'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Charlemagne-by-Durer.jpg/400px-Charlemagne-by-Durer.jpg',
    dates:'742 – 814',
    role:'Roi des Francs, Empereur d\'Occident',
